questionvariables.text:
coeff_3:rand(3)+3;
quest_expr:y^2+coeff_3*x;
eq_circle_1:x^2+y^2=1;
eq_circle_2:x^2+y^2=9;
y:r*sin(theta);
x:r*cos(theta);
dA:r;
/*worked solution variables*/
eqn1:(((y)^2)+coeff_3*(x)); /*writing in polar cordinates*/
eqn2:(eqn1)*r;
eqn3:expand(eqn2);
/*r integration*/
r_limit1:1;
r_limit2:3;
integration_1:int(eqn3,r);
soln1:1/2*(1-cos(2*theta));/*substitution for sin(theta)^2*/
soln2:subst(soln1,sin(theta)^2,integration_1);
r_integration:int(eqn3,r,r_limit1,r_limit2);

/*theta integration*/
theta1:%pi; 
theta2:(3/2)*%pi ;
integrating_2:int(r_integration,theta);
theta_integration:decimalplaces(int(r_integration,theta,theta1,theta2),2);

/*model answers*/
ta1:%pi;
ta2:(3/2)*%pi;
ta3:1;
ta4:3;
ta5:eqn1;
ta6:theta_integration;

feedbackvariables.text:
/*node 1:checks for correct answers*/
/*node 2:Giving the original expression*/
mistake5:quest_expr;

/*node 1:checks for correct answers*/
/*node 2:Differentiating instead of integrating*/
mistake6:decimalplaces(diff(r_integration,θ),2);
